let catalogSearch='',catalogPage=1;
function catalogAdmin(){return `<div class="catalog-toolbar"><label>Buscar peça<input id="admin-product-search" type="search" placeholder="Nome, categoria ou lavagem" value="${esc(catalogSearch)}"></label><button class="btn dark" data-new-product>+ Adicionar peça</button></div><div id="admin-product-list"></div>`;}
function renderAdminList(){const target=document.querySelector('#admin-product-list');if(!target)return;const q=catalogSearch.trim().toLocaleLowerCase('pt-BR');const filtered=products.filter(p=>(p.name+' '+p.type+' '+p.wash).toLocaleLowerCase('pt-BR').includes(q));const pages=Math.max(1,Math.ceil(filtered.length/12));catalogPage=Math.min(catalogPage,pages);target.innerHTML=`<p class="muted">${filtered.length} peça(s) cadastrada(s)</p><div class="catalog-list">${filtered.slice((catalogPage-1)*12,catalogPage*12).map(p=>`<article class="catalog-list-row"><img src="${productImage(p.image)}" alt=""><div><h2>${esc(p.name)}</h2><p>${esc(p.type)} · ${esc(p.wash)}</p><small>${(p.variants||[]).reduce((n,v)=>n+v.quantity,0)} unidades · ${(p.variants||[]).length} tamanhos</small></div><div class="catalog-row-actions"><button class="btn outline" data-edit-product="${p.id}" aria-label="Editar ${esc(p.name)}">Editar</button><button class="btn outline delete-product" data-delete-product="${p.id}" aria-label="Excluir ${esc(p.name)}">Excluir</button></div></article>`).join('')||'<div class="account-empty"><p>Nenhuma peça encontrada.</p></div>'}</div>${pages>1?`<div class="catalog-pagination"><button class="btn outline" data-catalog-page="${catalogPage-1}" ${catalogPage===1?'disabled':''}>Anterior</button><span>${catalogPage} de ${pages}</span><button class="btn outline" data-catalog-page="${catalogPage+1}" ${catalogPage===pages?'disabled':''}>Próxima</button></div>`:''}`;}
function productForm(p,isNew){return `<form class="product-editor" data-product="${isNew?'new':p.id}"><img src="${productImage(p.image)}" alt="${esc(p.name||'Nova peça')}"><div>${field('Nome da peça','name',p.name,'text','required minlength="2" maxlength="100"')}<label class="field">Categoria<select name="type">${categoryNames().map(t=>`<option value="${esc(t)}" ${p.type===t?'selected':''}>${esc(t)}</option>`).join('')}</select></label>${field('Lavagem','wash',p.wash,'text','required minlength="2" maxlength="80"')}<label class="field">Descrição<textarea name="description" required minlength="10" maxlength="1500">${esc(p.description)}</textarea></label>${isNew?'<fieldset class="photo-editor"><legend>Fotos da peça</legend><label class="photo-upload">Adicionar fotos<input type="file" data-new-photos multiple accept="image/jpeg,image/png,image/webp"></label><p class="muted">Até 8 fotos, até 8 MB cada. Serão enviadas ao salvar a peça.</p></fieldset>':photoEditor(p)}${stockEditor(p)}<p class="form-error" role="alert"></p><div class="product-form-actions"><button type="button" class="btn outline" data-close-product>Cancelar</button><button type="submit" class="btn dark">Salvar peça</button></div></div></form>`;}
function openProductEditor(id){let modal=document.querySelector('#product-dialog');if(!modal){modal=document.createElement('dialog');modal.id='product-dialog';modal.className='product-modal';modal.setAttribute('aria-labelledby','product-dialog-title');document.body.append(modal);modal.addEventListener('cancel',e=>{if(modal.querySelector('form')?.dataset.saving||modal.querySelector('.photo-editor')?.disabled)e.preventDefault();});modal.addEventListener('close',()=>{modal.innerHTML='';renderAdminList();});}const isNew=!id,p=isNew?{name:'',type:categoryNames()[0]||'',wash:'',description:'',image:'placeholder.svg',variants:[],photos:[],inventoryVersion:0}:products.find(p=>p.id===id);if(!p)return;modal.innerHTML=`<div class="dialog-head"><h2 id="product-dialog-title">${isNew?'Adicionar peça':'Editar peça'}</h2><button type="button" data-close-product aria-label="Fechar cadastro">×</button></div>${productForm(p,isNew)}`;modal.showModal();modal.scrollTop=0;}
document.addEventListener('input',e=>{if(e.target.id==='admin-product-search'){catalogSearch=e.target.value;catalogPage=1;renderAdminList();}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-new-product'))openProductEditor();if(b.dataset.editProduct)openProductEditor(b.dataset.editProduct);if(b.dataset.catalogPage){catalogPage=Number(b.dataset.catalogPage);renderAdminList();}if(b.hasAttribute('data-close-product')){const modal=b.closest('dialog');if(!modal.querySelector('form')?.dataset.saving&&!modal.querySelector('.photo-editor')?.disabled)modal.close();}});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.matches('[data-product]'))return;e.preventDefault();e.stopImmediatePropagation();if(form.dataset.saving)return;const error=form.querySelector('.form-error');error.textContent='';if(form.querySelector('.photo-editor')?.disabled){error.textContent='Aguarde o envio das fotos terminar.';return;}form.dataset.saving='true';const button=form.querySelector('[type="submit"]');button.disabled=true;button.textContent='Salvando…';let savedRecord=false;try{
 const values=Object.fromEntries(new FormData(form));values.variants=[...form.querySelectorAll('.stock-row')].map(row=>({size:row.querySelector('[data-stock-size]').value,quantity:Number(row.querySelector('[data-stock-quantity]').value)}));values.inventoryVersion=Number(form.querySelector('[data-version]').dataset.version);
 if(form.dataset.product==='new'){
  const files=[...(form.querySelector('[data-new-photos]')?.files||[])];if(files.length>8||files.some(f=>f.size>8*1024*1024||!['image/jpeg','image/png','image/webp'].includes(f.type)))throw Error('Escolha até 8 fotos JPG, PNG ou WebP de até 8 MB cada.');
  form.pendingUploads=await Promise.all(files.map(prepareUpload));const created=await api('admin/products','POST',values);form.dataset.product=created.id;form.querySelector('[data-version]').dataset.version=created.inventoryVersion;
 }else{await api('admin/products/'+form.dataset.product,'PATCH',values);}
 savedRecord=true;
 while(form.pendingUploads?.length){button.textContent='Enviando fotos…';await api('admin/products/'+form.dataset.product+'/photos','POST',{base64:form.pendingUploads[0]});form.pendingUploads.shift();}
 await loadProducts();document.querySelector('#product-dialog').close();renderAdminList();toast('Peça salva.');
 }catch(err){error.textContent=err.message;if(savedRecord&&form.dataset.product!=='new'){try{await loadProducts();const p=products.find(p=>p.id===form.dataset.product);if(p)form.querySelector('[data-version]').dataset.version=p.inventoryVersion;}catch{}}}finally{delete form.dataset.saving;button.disabled=false;button.textContent='Salvar peça';}},true);

window.addEventListener('hashchange',()=>{const modal=document.querySelector('#product-dialog');if(modal?.open)modal.close();});

document.addEventListener('click',async e=>{const button=e.target.closest('[data-delete-product]');if(!button||button.disabled)return;const p=products.find(p=>p.id===button.dataset.deleteProduct);if(!p||!confirm('Excluir a peça "'+p.name+'" do catálogo? Ela não poderá receber novas compras. Os pedidos anteriores serão mantidos.'))return;button.disabled=true;try{await api('admin/products/'+p.id,'DELETE',{});await loadProducts();renderAdminList();toast('Peça excluída do catálogo.');}catch(err){toast(err.message);}finally{button.disabled=false;}});
